// Format visible text only. Never alter URLs, identifiers, scripts or existing MathML.
function scientificTypography(root){
 if(!root||typeof document.createTreeWalker!=='function')return;
 const map={ 'μB':['μ','B'],'kBT':['k','B','sub','T'],'Fe3+':['Fe','3+','sup'],'Fe2+':['Fe','2+','sup'],'cm-1':['cm','−1','sup'],'m-3':['m','−3','sup'],'s-1':['s','−1','sup'],'MS,core':['M','S,core'],'MS,cœur':['M','S,cœur'],'mIRM':['m','IRM'],'mDCD':['m','DCD'],'τeff':['τ','eff'],'τN':['τ','N'],'τB':['τ','B'],'τ0':['τ','0'],'tm':['t','m'],'TB':['T','B'],'kB':['k','B'],'MS':['M','S'],'MR':['M','R'],'HC':['H','C'],'HK':['H','K'],'T1':['T','1'],'T2':['T','2'],'R1':['R','1'],'R2':['R','2'],'r1':['r','1'],'r2':['r','2'],'M0':['M','0'],'H0':['H','0'],'Vh':['V','h'],'Keff':['K','eff'],'ci':['c','i'],'zi':['z','i'] };
 const pattern=/(?<![A-Za-zÀ-ÿ])(?:μB|kBT|Fe3\+|Fe2\+|cm-1|m-3|s-1|MS,core|MS,cœur|mIRM|mDCD|τeff|τN|τB|τ0|tm|TB|kB|MS|MR|HC|HK|T1|T2|R1|R2|r1|r2|M0|H0|Vh|Keff|ci|zi)(?![A-Za-zÀ-ÿ])/g;
 const walker=document.createTreeWalker(root,4),nodes=[];let node;
 while(node=walker.nextNode())if(!node.parentElement?.closest('script,style,math,sub,sup,tspan,textarea,option'))nodes.push(node);
 for(const n of nodes){const text=n.nodeValue;if(!pattern.test(text)){pattern.lastIndex=0;continue}pattern.lastIndex=0;const frag=document.createDocumentFragment();let pos=0;for(const match of text.matchAll(pattern)){frag.append(document.createTextNode(text.slice(pos,match.index)));const [base,index,type="sub",tail=""]=map[match[0]];frag.append(document.createTextNode(base));const svg=n.parentElement.namespaceURI==='http://www.w3.org/2000/svg';const sub=svg?document.createElementNS('http://www.w3.org/2000/svg','tspan'):document.createElement(type);if(svg){sub.setAttribute('baseline-shift',type==='sup'?'super':'sub');sub.setAttribute('style','font-size:70%')}sub.textContent=index;frag.append(sub);if(tail)frag.append(document.createTextNode(tail));pos=match.index+match[0].length}frag.append(document.createTextNode(text.slice(pos)));n.replaceWith(frag);}
}
